!function(){var LANE_DENSITIES=[Math.pow(2,-12),Math.pow(2,-9),Math.pow(2,-6),Math.pow(2,-3),Math.pow(2,-2),Math.pow(2,-1),1];var api={LANE_DENSITIES:LANE_DENSITIES,laneMassesForCapacity:function(capacity){if(!isFinite(capacity)||capacity<=0)throw new Error("[collisionMatrixLanes] capacity must be a positive number, got "+JSON.stringify(capacity)+". Read it back from the engine after building a body (universe.getFrameProperty(qid, 'mass')) — never assume it.");return LANE_DENSITIES.map(function(rho){return Math.max(1,Math.min(capacity,Math.round(rho*capacity)))})}};"undefined"!=typeof module&&module.exports?module.exports=api:window.collisionMatrixLanes=api}();